import { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Login() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const login = async (e) => {
    e.preventDefault();
    setError("");

    console.log("LOGIN CLICKED", username, password);

    try {
      const res = await fetch("http://localhost:5001/admin/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ username, password }),
      });

      const data = await res.json();
      console.log("LOGIN RESPONSE", data);

      if (!res.ok) {
        setError(data.error || "Login failed");
        return;
      }

      if (data.token) {
        localStorage.setItem("adminToken", data.token);
        navigate("/admin"); // dashboard route
      } else {
        setError("Invalid username or password");
      }
    } catch (err) {
      console.error("LOGIN ERROR", err);
      setError("Server not reachable");
    }
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center">
      <form
        onSubmit={login}
        className="bg-black border border-white/10 p-10 rounded-2xl w-full max-w-md"
      >
        <h2 className="text-3xl font-bold text-[#e9b21a] mb-8 text-center">
          Admin Login
        </h2>

        {error && (
          <p className="text-red-500 text-center mb-4">{error}</p>
        )}

        <input
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          placeholder="Username"
          className="w-full mb-4 px-4 py-3 rounded bg-black border border-white/20 text-white"
          required
        />

        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Password"
          className="w-full mb-6 px-4 py-3 rounded bg-black border border-white/20 text-white"
          required
        />

        <button
          type="submit"
          className="w-full py-3 rounded-full bg-[#e9b21a] text-black font-semibold"
        >
          Login
        </button>
      </form>
    </div>
  );
}
